-- Verificacion v114 - Cuentas por cobrar de contratos. Solo lectura.
select to_regclass('public.contrato_cartera_v114')is not null cartera_ok,to_regclass('public.contrato_promesas_pago_v114')is not null promesas_ok,to_regclass('public.contrato_recordatorios_cobro_v114')is not null recordatorios_ok;
select to_regprocedure('public.listar_cartera_contratos_v114(text,text,date,date,integer,integer)')is not null listar_ok,to_regprocedure('public.obtener_cartera_contrato_v114(uuid)')is not null detalle_ok,to_regprocedure('public.registrar_promesa_pago_v114(uuid,date,numeric,text,uuid)')is not null promesa_ok,to_regprocedure('public.registrar_abono_cartera_v114(uuid,date,numeric,text,text,text,text,uuid)')is not null abono_ok,to_regprocedure('public.registrar_recordatorio_cobro_v114(uuid,text,text,date,uuid)')is not null recordatorio_ok;
select has_function_privilege('authenticated','public.listar_cartera_contratos_v114(text,text,date,date,integer,integer)','execute')consulta_ok,not has_function_privilege('anon','public.registrar_abono_cartera_v114(uuid,date,numeric,text,text,text,text,uuid)','execute')anon_bloqueado_ok,not has_table_privilege('authenticated','public.contrato_promesas_pago_v114','insert')insert_directo_bloqueado_ok;
select count(*)as contratos_sin_cartera_debe_ser_cero from public.contratos c left join public.contrato_cartera_v114 x on x.contrato_id=c.id where x.contrato_id is null;
select count(*)as contratos_con_dos_promesas_vigentes_debe_ser_cero from(select contrato_id from public.contrato_promesas_pago_v114 where estado='vigente'group by contrato_id having count(*)>1)x;
select count(*)as abonos_fuera_de_saldo_debe_ser_cero from public.contratos where abono>presupuesto;
select estado,count(*)promesas,coalesce(sum(monto_prometido),0)monto from public.contrato_promesas_pago_v114 group by estado order by estado;
